        call: String? = nil,
        qsoDate: ADIDate? = nil,
        timeOn: ADITime? = nil,
        band: ADIBand? = nil,
        mode: ADIMode? = nil,
        freq: Double? = nil,
        dxcc: ADIDXCCEntityCode? = nil
    ) {
        self.init()
        self.call = call
        self.qsoDate = qsoDate
        self.timeOn = timeOn
        self.band = band
        self.mode = mode
        self.freq = freq
        self.dxcc = dxcc
    }

    /// Parses one record from the text of an ADI record.
    ///
    /// - Parameter text: The record's fields, with or without the trailing `<EOR>`
    ///   tag. Free-form text before the first `<` is ignored, as the specification
    ///   requires. Fields this library does not recognize are collected into
    ///   ``unknownFields``.
    /// - Throws: ``ADIFError`` if a tag is malformed, if a field's data does not
    ///   match the type the specification gives it, or if a `<EOH>` tag appears
    ///   where a record field was expected.
    public init(parsing text: String) throws {
        self.init()

        var scanner = ADITagScanner(text)
        _ = scanner.consumeLeadingText()

        while let tag = try scanner.scanTag() {
            switch tag {
            case .endOfRecord:
                return
            case .endOfHeader:
                throw ADIFError.unexpectedTagInRecord(name: tag.name)
            case let .dataSpecifier(specifier):
                try apply(specifier)
            }
        }
    }

