    private mutating func apply(_ specifier: ADIDataSpecifier) throws {
        switch specifier.name {
        case "ADDRESS":
            address = specifier.data
        case "ADDRESS_INTL":
            addressIntl = specifier.data
        case "AGE":
            age = try ADIRecordCoder.number(specifier.data, field: "AGE")
        case "ALTITUDE":
            altitude = try ADIRecordCoder.number(specifier.data, field: "ALTITUDE")
        case "ANT_AZ":
            antAz = try ADIRecordCoder.number(specifier.data, field: "ANT_AZ")
        case "ANT_EL":
            antEl = try ADIRecordCoder.number(specifier.data, field: "ANT_EL")
        case "ANT_PATH":
            antPath = ADIRecordCoder.enumeration(specifier.data, as: ADIAntPath.self)
        case "ARRL_SECT":
            arrlSect = ADIRecordCoder.enumeration(specifier.data, as: ADIARRLSection.self)
        case "AWARD_SUBMITTED":
            awardSubmitted = ADIRecordCoder.enumerationList(specifier.data, as: ADISponsoredAward.self)
        case "AWARD_GRANTED":
            awardGranted = ADIRecordCoder.enumerationList(specifier.data, as: ADISponsoredAward.self)
        case "A_INDEX":
            aIndex = try ADIRecordCoder.number(specifier.data, field: "A_INDEX")
        case "BAND":
